const items = $input.all().map(i => i.json);
const lines = items.map((it, idx) => `${idx}. NPS=${it.nps} | ${(it.feedback || '').replace(/\n/g, ' ')}`).join('\n');
return [{ json: { items, promptText: lines } }];

// BUMP THIS whenever the strategy pillar set changes, so historical rows stay
// attributable to the frame they were classified under and trend lines do not
// silently break across a strategy revision.
const STRATEGY_VERSION = '2026-07-v1';

const original = $('Build Batch Prompt').first().json.items;
const classifications = $json.output || [];

const ALLOWED_CATEGORIES = ['UX', 'Reliability', 'Performance', 'Pricing', 'Integrations', 'Documentation', 'Learning Curve', 'Self-hosting/Deployment', 'Support', 'No Driver Named', 'Other'];
const ALLOWED_SENTIMENT = ['positive', 'negative', 'neutral'];
const ALLOWED_PILLARS = ['AI Building', 'Visual Auditability', 'Runtime Governance', 'Power & Ceiling', 'Setup & Activation', 'Agents vs Workflows', 'Self-hosting & Openness', 'Community & Ecosystem', 'None'];

const byIndex = {};
for (const c of classifications) {
  if (c && c.index !== undefined && c.index !== null) byIndex[Number(c.index)] = c;
}

let unmatched = 0, violations = 0, pillarViolations = 0;

const out = original.map((item, idx) => {
  const c = byIndex[idx];

  // Segmentation fields are pure pass-through on BOTH paths - already resolved
  // upstream (BigQuery/Triage), never derived here. Not used by today's digest.
  const segments = {
    deployment: item.deployment ?? 'NA',
    enterprise_tier: item.enterprise_tier ?? 'NA',
    role: item.role ?? 'NA',
    company_size: item.company_size ?? 'NA',
    tech_skills_count: item.tech_skills_count ?? 'NA',
  };

  // Classifier failed to return this line. Surface it as a visible anomaly row
  // rather than silently dropping the comment.
  // response_timestamp must be carried on THIS path too, not just the happy
  // path, or anomaly rows fall outside every reporting window.
  if (!c) {
    unmatched++;
    return { json: {
      feedback: item.feedback, nps: item.nps,
      response_timestamp: item.response_timestamp ?? null, backfilled: false,
      category: 'Other', category_secondary: '', sentiment: 'neutral',
      evidence: 'UNMATCHED_BY_CLASSIFIER', is_request: false, actionable: false,
      strategy_pillar: 'None', strategy_version: STRATEGY_VERSION,
      ...segments,
    } };
  }

  const evidence = typeof c.evidence === 'string' ? c.evidence.trim() : '';

  // Clamp enums in code. An out-of-enum Axis 1 category is TAGGED rather than
  // quietly folded into Other, because Other is the taxonomy-gap alarm.
  let category = c.category;
  let marker = '';
  if (!ALLOWED_CATEGORIES.includes(category)) {
    violations++;
    marker = `ENUM_VIOLATION(${category}) | `;
    category = 'Other';
  }

  let categorySecondary = ALLOWED_CATEGORIES.includes(c.category_secondary) ? c.category_secondary : '';
  if (categorySecondary === category) categorySecondary = '';
  const sentiment = ALLOWED_SENTIMENT.includes(c.sentiment) ? c.sentiment : 'neutral';

  // An invalid pillar defaults to None rather than being tagged: None is the
  // safe default here, and a bad pillar must never inflate a strategic count.
  let pillar = c.strategy_pillar;
  if (!ALLOWED_PILLARS.includes(pillar)) { pillarViolations++; pillar = 'None'; }
  // A No Driver Named row cannot address a strategic bet by definition.
  if (category === 'No Driver Named') pillar = 'None';

  return { json: {
    feedback: item.feedback, nps: item.nps,
    response_timestamp: item.response_timestamp ?? null, backfilled: false,
    category, category_secondary: categorySecondary, sentiment,
    evidence: marker + evidence,
    is_request: c.is_request === true,
    // Derived, not trusted: actionable iff a concrete phrase was quoted.
    // Judged on the real evidence, not on the violation marker.
    actionable: evidence.length > 0,
    strategy_pillar: pillar,
    strategy_version: STRATEGY_VERSION,
    ...segments,
  } };
});

if (unmatched > 0) console.warn(`[Zip] ${unmatched}/${original.length} lines not returned -> UNMATCHED_BY_CLASSIFIER`);
if (violations > 0) console.warn(`[Zip] ${violations}/${original.length} category outside enum -> tagged ENUM_VIOLATION`);
if (pillarViolations > 0) console.warn(`[Zip] ${pillarViolations}/${original.length} strategy_pillar outside enum -> defaulted to None`);

return out;

// Drop everything that cannot name a driver, pass the rest to classification.
// Thresholds derived from 90 days of real response frequencies, not guessed.
const LETTER = /\p{L}/u;
const LATIN_ONLY = /^[a-z0-9]+$/;

// Generic responses that carry a mood but name no driver. Multilingual, any
// length. Dropped, not stored - we are not tracking a junk rate.
const GENERIC = new Set([
  'good', 'goood', 'goog', 'god', 'great', 'nice', 'top', 'best', 'cool',
  'love', 'wow', 'thx', 'ty', 'thanks', 'thank', 'perfect', 'amazing',
  'awesome', 'awsome', 'excellent', 'excelent', 'excelente', 'super',
  'superb', 'otimo', 'bom', 'bien', 'genial', 'fantastic', 'wonderful',
  'wonderfull', 'happy', 'mantap', 'bagus', 'verygood', 'gracias', 'danke',
  'merci', 'ok', 'okay', 'oke', 'yes', 'si', 'no', 'na', 'idk', 'fine',
  'hi', 'hello', 'test', 'teste', 'meh', 'because', 'cause', 'nothing',
  'muito', 'mucho', 'mucha', 'muchas', 'todas', 'yeah', 'like',
  'bad', 'poor', 'sad', 'terrible', 'awful', 'horrible',
]);

// The ONLY short Latin tokens that name a driver. Verified against the full
// 90-day distribution: the <=4 char single-token space contains essentially no
// driver feedback apart from these.
const MEANINGFUL_SHORT = new Set([
  'free', 'easy', 'slow', 'fast', 'cost', 'bug', 'bugs', 'lag', 'hard',
  'ux', 'ui', 'api', 'mcp', 'sql', 'csv', 'crm', 'http', 'ai', 'llm',
  'docs', 'doc', 'node', 'save', 'paid', 'n8n',
]);

const out = [];
const dropped = { noLetters: 0, repeatedChar: 0, generic: 0, shortToken: 0, tinyTokens: 0 };
let missingTimestamp = 0;

for (const item of $input.all()) {
  const raw = (item.json.feedback ?? '').toString();
  const fb = raw.trim();

  // 1. No letters in any script -> respondent typed their score or a symbol
  //    into the text box ("10" x1,684, "." x1,070).
  if (!LETTER.test(fb)) { dropped.noLetters++; continue; }

  // \p{M} must be kept: Thai vowel signs, Hebrew niqqud and Arabic diacritics
  // are combining marks, not letters. Stripping them corrupts those languages.
  const norm = fb.toLowerCase().replace(/[^\p{L}\p{N}\p{M}\s]/gu, '').replace(/\s+/g, ' ').trim();
  const tokens = norm.split(' ').filter(Boolean);

  // 2. One character repeated, any length: mmm, fff, ddd, aaaa, TT.
  //    \1+ not \1* - with * this matches any single character and would
  //    wrongly drop single-character Chinese words.
  if (/^(.)\1+$/u.test(norm.replace(/\s/g, ''))) { dropped.repeatedChar++; continue; }

  // 3. A single generic word, any length, any language.
  if (tokens.length === 1 && GENERIC.has(tokens[0])) { dropped.generic++; continue; }

  // 4. MAIN GATE. A single Latin token of <=4 chars that is not a known driver
  //    word cannot carry signal. Non-Latin scripts skip this entirely, so
  //    Chinese and Hebrew short words are never dropped here.
  if (tokens.length === 1 && LATIN_ONLY.test(tokens[0]) && tokens[0].length <= 4 && !MEANINGFUL_SHORT.has(tokens[0])) {
    dropped.shortToken++;
    continue;
  }

  // 5. Multi-token where every token is Latin and <=2 chars: "sd sd", "a b c".
  if (tokens.length > 1 && tokens.every(t => LATIN_ONLY.test(t) && t.length <= 2)) {
    dropped.tinyTokens++;
    continue;
  }

  // response_timestamp is WHEN THE USER ANSWERED, carried from BigQuery.
  // Distinct from the data table's createdAt (when the row was written).
  // Period windows must filter on this, otherwise a backfill - where every row
  // is written on the same day - lands entirely inside one reporting period.
  if (!item.json.timestamp) missingTimestamp++;

  // Segmentation fields (deployment, enterprise_tier, role, company_size,
  // tech_skills_count) are pure pass-through, already resolved to 'NA' where
  // unknown by the BigQuery query. Not used by today's digest - captured for
  // future segmented reporting.
  out.push({ json: {
    feedback: raw,
    nps: item.json.nps,
    response_timestamp: item.json.timestamp ?? null,
    deployment: item.json.deployment ?? 'NA',
    enterprise_tier: item.json.enterprise_tier ?? 'NA',
    role: item.json.role ?? 'NA',
    company_size: item.json.company_size ?? 'NA',
    tech_skills_count: item.json.tech_skills_count ?? 'NA',
  } });
}

const totalDropped = Object.values(dropped).reduce((a, b) => a + b, 0);
console.log(`[Triage] in=${$input.all().length} dropped=${totalDropped} ${JSON.stringify(dropped)} toClassify=${out.length}`);
if (missingTimestamp > 0) console.warn(`[Triage] ${missingTimestamp}/${out.length} rows have NO response_timestamp - check the source query selects 'timestamp'`);

return out;

const original = $('Build Embedding Batch').first().json.items;
const data = ($json.data || []).slice().sort((a, b) => a.index - b.index);
return original.map((item, idx) => ({ json: { ...item, embedding: data[idx] ? data[idx].embedding : null } }));
